export default "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Right Window — Status</title>\n  <meta name=\"description\" content=\"Live health of Right Window's data pipeline: every record it reads from the city, when each was last published, and any source that has fallen off.\" />\n  <meta name=\"robots\" content=\"noindex\" />\n  <meta name=\"theme-color\" content=\"#0D1211\" media=\"(prefers-color-scheme: dark)\" />\n  <meta name=\"theme-color\" content=\"#F1EFE9\" media=\"(prefers-color-scheme: light)\" />\n  <link rel=\"icon\" href=\"/icon.svg\" type=\"image/svg+xml\" />\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link href=\"https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Public+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\" />\n  <style>\n    /* The site's own tokens (src/index.css), so this page is the same product. */\n    :root {\n      --bg-0: #F1EFE9; --grid: rgba(18, 26, 22, 0.05);\n      --paper: #FBFAF6; --paper-2: #FFFEFB;\n      --ink: #101613; --ink-2: #3E4B46; --ink-3: #5F6F69;\n      --line: rgba(15, 30, 26, 0.09); --line-2: rgba(15, 30, 26, 0.16);\n      --brand: #14594A; --brand-2: #0C3E33; --brand-wash: rgba(20, 89, 74, 0.10);\n      --warm: #77550A; --warm-wash: rgba(186, 141, 33, 0.14);\n      --bad: #A63A28; --bad-wash: rgba(166, 58, 40, 0.12);\n      --panel: rgba(255, 255, 255, 0.55);\n      --shadow: 0 1px 2px rgba(15, 30, 26, 0.04), 0 12px 32px -18px rgba(15, 30, 26, 0.22);\n      --sans: 'Public Sans', -apple-system, 'Segoe UI', sans-serif;\n      --display: 'Instrument Serif', 'Iowan Old Style', Georgia, serif;\n      --mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;\n      --r: 10px; --r-sm: 6px;\n    }\n    @media (prefers-color-scheme: dark) {\n      :root:not([data-theme=\"light\"]) {\n        --bg-0: #0D1211; --grid: rgba(255, 255, 255, 0.038);\n        --paper: #151B19; --paper-2: #1A211E;\n        --ink: #E5ECE9; --ink-2: #A6B5AF; --ink-3: #93A29C;\n        --line: rgba(255, 255, 255, 0.09); --line-2: rgba(255, 255, 255, 0.17);\n        --brand: #56B99D; --brand-2: #7FCDB4; --brand-wash: rgba(86, 185, 157, 0.13);\n        --warm: #D9A94A; --warm-wash: rgba(217, 169, 74, 0.14);\n        --bad: #E07A66; --bad-wash: rgba(224, 122, 102, 0.14);\n        --panel: rgba(255, 255, 255, 0.05);\n        --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 12px 32px -18px rgba(0, 0, 0, 0.55);\n      }\n    }\n    :root[data-theme=\"dark\"] {\n      --bg-0: #0D1211; --grid: rgba(255, 255, 255, 0.038);\n      --paper: #151B19; --paper-2: #1A211E;\n      --ink: #E5ECE9; --ink-2: #A6B5AF; --ink-3: #93A29C;\n      --line: rgba(255, 255, 255, 0.09); --line-2: rgba(255, 255, 255, 0.17);\n      --brand: #56B99D; --brand-2: #7FCDB4; --brand-wash: rgba(86, 185, 157, 0.13);\n      --warm: #D9A94A; --warm-wash: rgba(217, 169, 74, 0.14);\n      --bad: #E07A66; --bad-wash: rgba(224, 122, 102, 0.14);\n      --panel: rgba(255, 255, 255, 0.05);\n      --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 12px 32px -18px rgba(0, 0, 0, 0.55);\n    }\n    * { box-sizing: border-box; }\n    html, body { margin: 0; }\n    body {\n      color: var(--ink);\n      font: 15px/1.5 var(--sans);\n      font-variant-numeric: tabular-nums;\n      -webkit-font-smoothing: antialiased;\n      background:\n        linear-gradient(to right, var(--grid) 1px, transparent 1px) 0 0 / 96px 96px,\n        linear-gradient(to bottom, var(--grid) 1px, transparent 1px) 0 0 / 96px 96px,\n        var(--bg-0);\n      background-attachment: fixed;\n      min-height: 100vh;\n    }\n    a { color: inherit; }\n    .wrap { max-width: 1080px; margin: 0 auto; padding: 20px 16px 64px; }\n\n    header { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }\n    .brand { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; font-weight: 600; }\n    .brand svg { width: 22px; height: 22px; color: var(--brand); }\n    .brand span { color: var(--ink-3); font-weight: 500; }\n    .tools { display: flex; align-items: center; gap: 8px; }\n    .chip {\n      display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px;\n      border: 1px solid var(--line-2); border-radius: 999px; background: var(--panel);\n      color: var(--ink-2); font: 500 13px/1 var(--sans); text-decoration: none; cursor: pointer;\n    }\n    .chip:hover { color: var(--ink); border-color: var(--ink-3); }\n    .chip:focus-visible, button:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }\n    .chip.icon { width: 32px; padding: 0; justify-content: center; }\n\n    .lede { margin: 34px 0 26px; }\n    .eyebrow { font: 500 11.5px/1 var(--mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-3); display: flex; align-items: center; gap: 8px; }\n    .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--brand); box-shadow: 0 0 0 3px var(--brand-wash); }\n    .dot.warn { background: var(--warm); box-shadow: 0 0 0 3px var(--warm-wash); }\n    .dot.bad { background: var(--bad); box-shadow: 0 0 0 3px var(--bad-wash); }\n    .dot.live { animation: pulse 2.2s ease-in-out infinite; }\n    @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }\n    @media (prefers-reduced-motion: reduce) { .dot.live { animation: none; } }\n    h1 { font: 400 clamp(30px, 4.6vw, 46px)/1.08 var(--display); letter-spacing: -0.01em; margin: 10px 0 8px; text-wrap: balance; max-width: 22ch; }\n    h1 em { font-style: italic; color: var(--brand); }\n    h1 em.warn { color: var(--warm); }\n    h1 em.bad { color: var(--bad); }\n    .sub { color: var(--ink-2); max-width: 64ch; margin: 0; }\n    .sub .mono { font-family: var(--mono); font-size: 13px; color: var(--ink-3); }\n\n    h2 { font: 500 11.5px/1 var(--mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-3); margin: 34px 0 12px; display: flex; align-items: baseline; gap: 10px; }\n    h2 small { font: 400 12px/1 var(--mono); letter-spacing: 0; text-transform: none; color: var(--ink-3); }\n\n    .lanes { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }\n    @media (max-width: 820px) { .lanes { grid-template-columns: 1fr; } }\n    .card { background: var(--paper); border: 1px solid var(--line); border-radius: var(--r); box-shadow: var(--shadow); padding: 16px 18px; min-width: 0; }\n    .card .k { font: 500 11px/1 var(--mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-3); display: flex; align-items: center; justify-content: space-between; gap: 8px; }\n    .card .v { font: 400 30px/1.1 var(--display); margin: 10px 0 4px; letter-spacing: -0.01em; }\n    .card .v small { font: 400 15px/1 var(--sans); color: var(--ink-3); margin-left: 6px; }\n    .card .l { color: var(--ink-2); font-size: 13.5px; margin: 2px 0; }\n    .card .l b { font-weight: 600; color: var(--ink); }\n    .card .l.mono { font-family: var(--mono); font-size: 12.5px; color: var(--ink-3); }\n\n    .pill { display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 9px; border-radius: 999px; font: 600 11px/1 var(--mono); letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; }\n    .pill.ok { color: var(--brand); background: var(--brand-wash); }\n    .pill.warn { color: var(--warm); background: var(--warm-wash); }\n    .pill.bad { color: var(--bad); background: var(--bad-wash); }\n    .pill.mute { color: var(--ink-3); background: var(--panel); border: 1px solid var(--line); }\n\n    /* 24 hours in 96 cells: a gap in the five-minute lane is visible as a gap. */\n    .strip { display: grid; grid-template-columns: repeat(96, 1fr); gap: 1px; height: 18px; margin: 12px 0 4px; }\n    .strip i { background: var(--line-2); border-radius: 1px; }\n    .strip i.on { background: var(--brand); opacity: 0.75; }\n    .strip i.now { background: var(--brand); opacity: 1; }\n    .strip-legend { display: flex; justify-content: space-between; font: 400 10.5px/1 var(--mono); color: var(--ink-3); }\n\n    table { width: 100%; border-collapse: collapse; background: var(--paper); border: 1px solid var(--line); border-radius: var(--r); box-shadow: var(--shadow); overflow: hidden; }\n    .tablewrap { overflow-x: auto; border-radius: var(--r); }\n    th, td { text-align: left; padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: top; font-size: 13.5px; }\n    th { font: 500 11px/1 var(--mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-3); background: var(--panel); white-space: nowrap; }\n    tr:last-child td { border-bottom: 0; }\n    td.mono, .mono { font-family: var(--mono); font-size: 12.5px; }\n    td .name { font-weight: 600; }\n    td .agency { color: var(--ink-3); font: 400 12px/1.3 var(--mono); }\n    td .note { color: var(--ink-3); font-size: 12.5px; display: block; margin-top: 2px; }\n    td.nowrap, td.nowrap .note { white-space: nowrap; }\n    td a.ds { color: var(--ink-3); text-decoration: none; border-bottom: 1px dotted var(--line-2); }\n    td a.ds:hover { color: var(--ink); }\n\n    .list { display: flex; flex-direction: column; gap: 8px; }\n    .row { display: grid; grid-template-columns: 148px 1fr; gap: 12px; padding: 12px 16px; background: var(--paper); border: 1px solid var(--line); border-radius: var(--r); box-shadow: var(--shadow); }\n    @media (max-width: 560px) { .row { grid-template-columns: 1fr; gap: 4px; } }\n    .row .when { font: 500 12.5px/1.5 var(--mono); color: var(--ink-3); }\n    .row .what { min-width: 0; }\n    .row .what b { font-weight: 600; }\n    .row .what .d { color: var(--ink-2); font-size: 13px; }\n    .row .what .err { font-family: var(--mono); font-size: 12px; color: var(--ink-3); word-break: break-word; margin-top: 2px; }\n    .row.bad { border-left: 3px solid var(--bad); }\n    .row.warn { border-left: 3px solid var(--warm); }\n    .row.ok { border-left: 3px solid var(--brand); }\n    .row.mute { border-left: 3px solid var(--line-2); }\n    .empty { color: var(--ink-3); padding: 14px 16px; background: var(--paper); border: 1px dashed var(--line-2); border-radius: var(--r); }\n\n    .foot { margin-top: 44px; color: var(--ink-3); font-size: 12.5px; line-height: 1.6; max-width: 72ch; }\n    .foot code { font-family: var(--mono); font-size: 12px; }\n    .err-banner { background: var(--bad-wash); color: var(--bad); border: 1px solid var(--bad); border-radius: var(--r); padding: 12px 16px; margin-bottom: 16px; font-weight: 500; }\n    .hidden { display: none; }\n  </style>\n</head>\n<body>\n  <div class=\"wrap\">\n    <header>\n      <a class=\"brand\" href=\"/\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n          <rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"3\" />\n          <rect x=\"8\" y=\"8\" width=\"8\" height=\"8\" rx=\"1\" fill=\"currentColor\" stroke=\"none\" opacity=\"0.9\" />\n        </svg>\n        Right Window <span>· Status</span>\n      </a>\n      <div class=\"tools\">\n        <span class=\"chip mono\" id=\"clock\" title=\"New York time\">— ET</span>\n        <button class=\"chip icon\" id=\"theme\" type=\"button\" title=\"Switch theme\" aria-label=\"Switch theme\">\n          <svg id=\"theme-sun\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4.2\" /><path d=\"M12 2.5v2M12 19.5v2M4.6 4.6l1.4 1.4M18 18l1.4 1.4M2.5 12h2M19.5 12h2M4.6 19.4 6 18M18 6l1.4-1.4\" /></svg>\n          <svg id=\"theme-moon\" width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z\" /></svg>\n        </button>\n        <a class=\"chip\" href=\"/\">← The feed</a>\n        <a class=\"chip\" href=\"/status?signout=1\" title=\"Forget this browser\">Sign out</a>\n      </div>\n    </header>\n\n    <div id=\"fetch-error\" class=\"err-banner hidden\"></div>\n\n    <section class=\"lede\">\n      <div class=\"eyebrow\"><i class=\"dot live\" id=\"overall-dot\"></i><span id=\"overall-eyebrow\">Reading the city</span></div>\n      <h1 id=\"headline\">Reading the city <em>every hour.</em></h1>\n      <p class=\"sub\" id=\"sub\">Loading the pipeline…</p>\n    </section>\n\n    <h2>The pipeline <small id=\"pipeline-note\"></small></h2>\n    <div class=\"lanes\" id=\"lanes\"></div>\n\n    <h2>Records read <small>the city's clock is the publisher's own rowsUpdatedAt</small></h2>\n    <div class=\"tablewrap\"><table id=\"sources\"><thead><tr>\n      <th>Record</th><th>City published</th><th>Hourly sweep</th><th>5-minute probe</th><th>State</th>\n    </tr></thead><tbody></tbody></table></div>\n\n    <h2>Incidents <small>30 days · a failed read of a record's rows opens one; the next clean read closes it</small></h2>\n    <div class=\"list\" id=\"incidents\"></div>\n\n    <h2>Activity <small id=\"activity-note\">last 48 hours, newest first</small></h2>\n    <div class=\"list\" id=\"activity\"></div>\n\n    <p class=\"foot\">\n      Two lanes read the city. A five-minute lane re-checks contract awards and liquor licences and reads every record's\n      clock; an hourly lane rebuilds the whole feed. Each request is attributed to its record, so a failure here names the\n      source, not the run. A clock read is shown beside its record but never decides its state: only a failed read of the rows\n      opens an incident. The five-minute figures are at most a minute old; the hourly report is committed to the repository and\n      can be up to five minutes behind. Times are New York. <code>/api/status</code> is the same data as JSON, behind the same key.\n    </p>\n  </div>\n\n  <script>\n    // ---- theme, the same key the app uses (rw.theme, JSON-encoded) ----\n    const root = document.documentElement;\n    const readTheme = () => { try { return JSON.parse(localStorage.getItem('rw.theme')); } catch { return null; } };\n    const applyTheme = (t) => { if (t === 'dark' || t === 'light') root.setAttribute('data-theme', t); else root.removeAttribute('data-theme'); paintThemeBtn(); };\n    const isDark = () => root.getAttribute('data-theme') === 'dark' || (!root.getAttribute('data-theme') && matchMedia('(prefers-color-scheme: dark)').matches);\n    const paintThemeBtn = () => { document.getElementById('theme-sun').style.display = isDark() ? '' : 'none'; document.getElementById('theme-moon').style.display = isDark() ? 'none' : ''; };\n    applyTheme(new URLSearchParams(location.search).get('theme') || readTheme());\n    document.getElementById('theme').addEventListener('click', () => {\n      const next = isDark() ? 'light' : 'dark';\n      try { localStorage.setItem('rw.theme', JSON.stringify(next)); } catch {}\n      applyTheme(next);\n    });\n\n    // ---- time ----\n    const ET = 'America/New_York';\n    const HOUR = 3600000, DAY = 24 * HOUR;\n    const t = (v) => (v ? +new Date(v) : 0);\n    const ago = (v, now = Date.now()) => {\n      const ms = now - t(v); if (!t(v)) return 'never';\n      const m = Math.max(0, Math.round(ms / 60000));\n      if (m < 1) return 'just now'; if (m < 60) return `${m}m ago`;\n      const h = Math.floor(m / 60); if (h < 48) return `${h}h ${m % 60}m ago`;\n      return `${Math.floor(h / 24)}d ${h % 24}h ago`;\n    };\n    const dur = (ms) => { if (ms == null) return ''; const s = Math.round(ms / 1000); return s < 60 ? `${s}s` : s < 3600 ? `${Math.floor(s / 60)}m ${s % 60}s` : `${Math.floor(s / 3600)}h ${Math.floor((s % 3600) / 60)}m`; };\n    const etTime = (v) => new Date(t(v)).toLocaleTimeString('en-US', { timeZone: ET, hour: 'numeric', minute: '2-digit' });\n    const etDate = (v) => new Date(t(v)).toLocaleDateString('en-US', { timeZone: ET, month: 'short', day: 'numeric' });\n    const etStamp = (v, now = Date.now()) => {\n      const d = new Date(t(v));\n      const today = new Date(now).toLocaleDateString('en-US', { timeZone: ET }) === d.toLocaleDateString('en-US', { timeZone: ET });\n      return today ? `${etTime(v)} ET` : `${etDate(v)} · ${etTime(v)} ET`;\n    };\n    const esc = (s) => String(s ?? '').replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n    const n = (x) => Number(x || 0).toLocaleString('en-US');\n\n    setInterval(() => { document.getElementById('clock').textContent = new Date().toLocaleTimeString('en-US', { timeZone: ET, hour: 'numeric', minute: '2-digit' }) + ' ET'; }, 1000);\n\n    // ---- data ----\n    const API = new URLSearchParams(location.search).get('api') || '/api/status';\n    let data = null;\n    let lastFetchAt = 0;\n\n    async function load() {\n      try {\n        const r = await fetch(API, { cache: 'no-store' });\n        if (!r.ok) throw new Error(`HTTP ${r.status}`);\n        data = await r.json();\n        lastFetchAt = Date.now();\n        document.getElementById('fetch-error').classList.add('hidden');\n      } catch (e) {\n        const b = document.getElementById('fetch-error');\n        b.textContent = `Could not reach /api/status (${e.message}). Showing the last response${data ? ` from ${etTime(lastFetchAt)} ET` : ''}.`;\n        b.classList.remove('hidden');\n      }\n      render();\n    }\n\n    // ---- derived state ----\n    const PINGER_LATE_MS = 15 * 60000;   // three missed ticks\n    const FEED_STALE_MS = 6 * HOUR;      // the collector's own STALE_HOURS\n    const EXTRA = { enrichment: 'Contact search provider', dataBranch: 'Data branch (GitHub)', store: 'Private store (Vercel Blob)' };\n    const labelOf = (S, key) => S[key]?.label || EXTRA[key] || key;\n\n    function derive(d, now) {\n      const S = d.sources || {};\n      const live = d.live, hourly = d.hourly, last = hourly?.last || null;\n      const wf = d.workflows || [];\n      const runsOf = (name) => wf.filter((r) => r.name === name);\n      // A scheduled run that lands within 45 minutes of another sweep steps\n      // aside in seconds (refresh.yml, the gate job). It is not a sweep and\n      // must not stand in for the last one. A real sweep takes minutes, and\n      // one that dies in seconds concludes as a failure, not a success.\n      const steppedAside = (r) => r.event === 'schedule' && r.conclusion === 'success' && t(r.updatedAt) - t(r.startedAt) < 2 * 60000;\n      const refreshRuns = runsOf('refresh-data').filter((r) => !steppedAside(r));\n      const lastRefresh = refreshRuns[0] || null;\n      const lastDigest = runsOf('daily-digest')[0] || null;\n      const pingerRunning = runsOf('pinger').some((r) => r.status === 'in_progress' || r.status === 'queued');\n\n      // Per-record state, from both lanes.\n      const stamps = { ...(hourly?.last?.sourcesAt || {}), ...(live?.sourcesAt || {}) };\n      const rows = Object.entries(S).map(([key, s]) => {\n        const clock = t(stamps[key]) || 0;\n        const h = last?.sources?.[key] || null;\n        const f = live?.health?.sources?.[key] || null;\n        // The latest read of the publisher's clock, whichever lane made it.\n        const clockRead = [h?.clock, f?.clock].filter(Boolean).sort((a, b) => t(b.at) - t(a.at))[0] || null;\n        const openInc = [...(hourly?.incidents || []), ...(live?.health?.incidents || [])].find((i) => i.source === key && !i.resolvedAt) || null;\n        let state = 'ok', why = '';\n        if (openInc) { state = 'down'; why = `HTTP ${openInc.status ?? '—'} since ${etStamp(openInc.at, now)} · ${openInc.lane} lane`; }\n        // An unread clock leaves the last stamp standing; calling that \"the\n        // publisher has gone quiet\" would be our miss told as theirs.\n        else if (!s.lookup && clockRead?.ok === false) { state = 'noclock'; why = `the publisher's clock did not answer ${ago(clockRead.at, now)} (HTTP ${clockRead.status ?? '—'}) — the stamp shown is the last one read`; }\n        else if (!s.lookup && clock && s.staleAfter && now - clock > s.staleAfter * HOUR) { state = 'stale'; why = `the publisher has not loaded rows for ${Math.floor((now - clock) / DAY)}d — their side, not ours`; }\n        else if ((h?.retries || 0) > 0 || (f?.retries || 0) > 0) { state = 'retried'; why = `answered after ${(h?.retries || 0) + (f?.retries || 0)} retr${(h?.retries || 0) + (f?.retries || 0) === 1 ? 'y' : 'ies'}`; }\n        else if (!clock && !h && !f) { state = 'unknown'; why = 'not read yet'; }\n        return { key, ...s, clock, h, f, state, why, openInc };\n      });\n      // Lookups are read only when a card needs them; a clockless, untouched lookup is not news.\n      const shown = rows.filter((r) => !r.lookup || r.h || r.f || r.openInc);\n      // Lines that are not datasets: the search provider and the run itself.\n      const extras = Object.keys(EXTRA).map((key) => {\n        const h = last?.sources?.[key]; const f = live?.health?.sources?.[key];\n        if (!h && !f) return null;\n        const openInc = [...(hourly?.incidents || []), ...(live?.health?.incidents || [])].find((i) => i.source === key && !i.resolvedAt) || null;\n        const failing = openInc || h?.ok === false || f?.ok === false;\n        const state = !failing ? 'ok' : key === 'enrichment' ? 'refused' : 'down';\n        const why = failing ? `${(h || f)?.error || ''}`.slice(0, 120) : '';\n        return { key, label: EXTRA[key], agency: key === 'enrichment' ? 'licensed provider' : 'infrastructure', clock: 0, h, f, state, why, openInc, extra: true };\n      }).filter(Boolean);\n\n      const openIncidents = [...(hourly?.incidents || []), ...(live?.health?.incidents || [])].filter((i) => !i.resolvedAt);\n      const pingerLate = !live?.checkedAt || now - live.checkedAt > PINGER_LATE_MS;\n      const feedAt = t(last?.feedAt) || 0;\n      // Before the first report exists GitHub's run history stands in; no\n      // history at all is unknown, not stale.\n      const lastSweepAt = feedAt || t(lastRefresh?.startedAt) || 0;\n      const feedStale = lastSweepAt ? now - lastSweepAt > FEED_STALE_MS : false;\n      const refreshFailed = lastRefresh?.conclusion === 'failure' || lastRefresh?.conclusion === 'timed_out';\n      const runFailed = last?.outcome === 'failed';\n\n      // head: short enough for the headline; text: the whole story for the line under it.\n      const problems = [];\n      for (const r of shown) if (r.state === 'down') problems.push({ level: 'bad', head: `${r.label} is unreachable`, text: `${r.label}: ${r.why}` });\n      // The search provider is not the city: a spent quota is a warning with a name, not an outage.\n      for (const r of extras) if (r.state !== 'ok') problems.push({ level: r.state === 'refused' ? 'warn' : 'bad', head: `${r.label} ${r.state === 'refused' ? 'refused' : 'is failing'}`, text: `${r.label}: ${r.why}` });\n      if (pingerLate) problems.push({ level: 'bad', head: 'the five-minute lane has gone quiet', text: `the five-minute lane last checked ${ago(live?.checkedAt, now)}` });\n      if (feedStale) problems.push({ level: 'bad', head: 'the feed is stale', text: `the feed was last rebuilt ${ago(lastSweepAt, now)}` });\n      if (runFailed) problems.push({ level: 'bad', head: 'the hourly sweep crashed', text: `the last hourly sweep crashed: ${last.error || 'no message'}` });\n      if (refreshFailed && !runFailed) problems.push({ level: 'bad', head: 'the last hourly run failed on GitHub', text: `GitHub reports the last hourly run as ${lastRefresh.conclusion}` });\n      for (const r of shown) if (r.state === 'noclock') problems.push({ level: 'warn', head: `${r.label}'s clock did not answer`, text: `${r.label}: ${r.why}` });\n      for (const r of shown) if (r.state === 'stale') problems.push({ level: 'warn', head: `${r.label} has gone quiet at the publisher`, text: `${r.label}: ${r.why}` });\n      if (last?.outcome === 'upstream') problems.push({ level: 'warn', head: 'the last sweep stopped early', text: `the last hourly sweep stopped early — the city's API was unavailable — and kept the previous feed` });\n      if (last?.outcome === 'degraded') problems.push({ level: 'warn', head: 'the last sweep carried one stage', text: `the last hourly sweep ${last.error || 'carried one stage from the previous hour'}` });\n      if (live?.health?.outcome === 'degraded') problems.push({ level: 'warn', head: 'the five-minute lane is carrying a list', text: `the five-minute lane ${live.health.error || 'carried a previous list'}` });\n      for (const r of shown) if (r.state === 'retried') problems.push({ level: 'warn', head: `${r.label} needed retries`, text: `${r.label} ${r.why}` });\n      problems.sort((a, b) => (a.level === 'bad' ? 0 : 1) - (b.level === 'bad' ? 0 : 1));\n\n      const level = problems.some((p) => p.level === 'bad') ? 'bad' : problems.length ? 'warn' : 'ok';\n      return { S, live, hourly, last, wf, lastRefresh, lastDigest, pingerRunning, refreshRuns, rows: shown, extras, openIncidents, pingerLate, feedAt, feedStale, problems, level };\n    }\n\n    // ---- render ----\n    function render() {\n      if (!data) return;\n      const now = Date.now();\n      const v = derive(data, now);\n      renderLede(v, now);\n      renderLanes(v, now);\n      renderSources(v, now);\n      renderIncidents(v, now);\n      renderActivity(v, now);\n    }\n\n    function renderLede(v, now) {\n      const dot = document.getElementById('overall-dot');\n      dot.className = 'dot live' + (v.level === 'bad' ? ' bad' : v.level === 'warn' ? ' warn' : '');\n      const bad = v.problems.filter((p) => p.level === 'bad');\n      const warn = v.problems.filter((p) => p.level === 'warn');\n      document.getElementById('overall-eyebrow').textContent =\n        v.level === 'bad' ? `${bad.length} problem${bad.length > 1 ? 's' : ''} right now` : v.level === 'warn' ? `${warn.length} thing${warn.length > 1 ? 's' : ''} to know` : 'All records reading';\n      const h = document.getElementById('headline');\n      if (v.level === 'bad') h.innerHTML = `Something fell off: <em class=\"bad\">${esc(bad[0].head)}.</em>`;\n      else if (v.level === 'warn') h.innerHTML = `Reading the city. <em class=\"warn\">${esc(warn[0].head[0].toUpperCase() + warn[0].head.slice(1))}.</em>`;\n      else h.innerHTML = `Reading the city <em>every hour.</em>`;\n      const cityBy = v.live?.cityBy && v.S[v.live.cityBy] ? v.S[v.live.cityBy].label : null;\n      const city = t(v.live?.cityAt);\n      const parts = [];\n      if (city) parts.push(`The city last published ${ago(city, now)}${cityBy ? ` (${cityBy})` : ''}`);\n      if (v.live?.checkedAt) parts.push(`we last checked ${ago(v.live.checkedAt, now)}`);\n      if (v.feedAt) parts.push(`the feed was rebuilt ${ago(v.feedAt, now)}`);\n      const rest = v.problems.map((p) => p.text);\n      document.getElementById('sub').innerHTML =\n        esc(parts.join(' · ') + '.') +\n        (rest.length ? `<br>${esc(rest.join('; ') + '.')}` : '') +\n        ` <span class=\"mono\">Updated ${ago(lastFetchAt, now)} · refreshes every minute</span>`;\n    }\n\n    function renderLanes(v, now) {\n      const live = v.live, last = v.last;\n      const el = document.getElementById('lanes');\n      const checks = (live?.pulse || []).filter((x) => now - x < DAY).length;\n      const strip = (() => {\n        const cells = new Array(96).fill(0);\n        for (const x of live?.pulse || []) { const i = Math.floor((now - x) / (15 * 60000)); if (i >= 0 && i < 96) cells[95 - i]++; }\n        return `<div class=\"strip\" aria-label=\"checks in the last 24 hours, 15-minute cells\">${cells.map((c, i) => `<i class=\"${c ? (i === 95 ? 'now' : 'on') : ''}\" title=\"${c} check${c === 1 ? '' : 's'}\"></i>`).join('')}</div><div class=\"strip-legend\"><span>24h ago</span><span>now</span></div>`;\n      })();\n      const fastPill = v.pingerLate ? '<span class=\"pill bad\">delayed</span>' : live?.health?.outcome === 'degraded' ? '<span class=\"pill warn\">carrying</span>' : '<span class=\"pill ok\">running</span>';\n      const lastNew = live?.changedAt ? ago(live.changedAt, now) : '—';\n      const fastNote = v.pingerLate\n        ? `last check ${ago(live?.checkedAt, now)} — ${v.pingerRunning ? 'a runner is up, waiting for its first tick' : 'no runner in progress on GitHub'}`\n        : `${v.pingerRunning ? 'runner in progress' : 'between runners'} · next tick in about ${Math.max(0, Math.round((5 * 60000 - (now - live.checkedAt)) / 60000))} min`;\n\n      const outcome = last?.outcome;\n      const hourlyPill = v.feedStale || outcome === 'failed' ? '<span class=\"pill bad\">' + (outcome === 'failed' ? 'crashed' : 'stale') + '</span>'\n        : !last ? (v.lastRefresh?.status === 'in_progress' ? '<span class=\"pill ok\">sweeping now</span>' : '<span class=\"pill mute\">no report yet</span>')\n        : outcome === 'upstream' ? '<span class=\"pill warn\">city unavailable</span>'\n        : outcome === 'degraded' ? '<span class=\"pill warn\">degraded</span>'\n        : v.lastRefresh?.status === 'in_progress' ? '<span class=\"pill ok\">sweeping now</span>'\n        : '<span class=\"pill ok\">ok</span>';\n      const c = last?.counts || {};\n      const failed = Object.entries(last?.sources || {}).filter(([, s]) => s.ok === false).map(([k]) => labelOf(v.S, k));\n      const starts = v.refreshRuns.slice(0, 5).map((r) => etTime(r.startedAt)).join(' · ');\n      const digest = v.lastDigest;\n\n      el.innerHTML = `\n        <div class=\"card\">\n          <div class=\"k\"><span>Every 5 minutes · intraday</span>${fastPill}</div>\n          <div class=\"v\">${live?.checkedAt ? esc(ago(live.checkedAt, now)) : '—'}<small>last check</small></div>\n          <div class=\"l\"><b>${n(checks)}</b> checks in the last 24 hours · last new signal <b>${esc(lastNew)}</b></div>\n          ${strip}\n          <div class=\"l mono\">${esc(fastNote)}</div>\n        </div>\n        <div class=\"card\">\n          <div class=\"k\"><span>Every hour · full sweep</span>${hourlyPill}</div>\n          <div class=\"v\">${v.feedAt ? esc(ago(v.feedAt, now)) : '—'}<small>feed rebuilt</small></div>\n          <div class=\"l\">${last ? `Last run ${esc(etStamp(last.startedAt, now))} · ${esc(dur(last.ms))} · <b>${esc(outcome)}</b>${failed.length ? ` · failed: <b>${esc(failed.join(', '))}</b>` : ''}` : 'No run report yet — the first report lands with the next hourly run.'}</div>\n          <div class=\"l\">${c.facades ? `${n(c.facades)} facade buildings · ${n(c.permits)} with a facade permit · ${n(c.gas)} gas · ${n(c.elevators)} elevators · ${n(c.carbon)} carbon · ${n(c.contracts)} contracts · ${n(c.openings)} openings` : ''}</div>\n          <div class=\"l mono\">${starts ? `GitHub started sweeps at ${esc(starts)}` : 'run history unavailable'}${v.lastRefresh?.status === 'in_progress' ? ' · one is running now' : ''}</div>\n        </div>\n        <div class=\"card\">\n          <div class=\"k\"><span>Daily · digest email</span>${digest ? (digest.conclusion === 'success' ? '<span class=\"pill ok\">sent</span>' : digest.status === 'in_progress' ? '<span class=\"pill ok\">sending</span>' : `<span class=\"pill bad\">${esc(digest.conclusion || digest.status)}</span>`) : '<span class=\"pill mute\">no run</span>'}</div>\n          <div class=\"v\">${digest ? esc(ago(digest.startedAt, now)) : '—'}<small>last run</small></div>\n          <div class=\"l\">${digest ? `${esc(etStamp(digest.startedAt, now))} · <a href=\"${esc(digest.url)}\" target=\"_blank\" rel=\"noopener\">run on GitHub</a>` : 'No digest run in the recent history.'}</div>\n          <div class=\"l mono\">Scheduled 8:07 AM ET · one email per subscriber with what the city published overnight</div>\n        </div>`;\n      document.getElementById('pipeline-note').textContent = v.wf.length ? '' : 'GitHub run history unavailable (rate limit) — the two lanes report for themselves';\n    }\n\n    const PILL = { ok: '<span class=\"pill ok\">ok</span>', noclock: '<span class=\"pill warn\">clock unread</span>', stale: '<span class=\"pill warn\">publisher quiet</span>', retried: '<span class=\"pill warn\">retried</span>', refused: '<span class=\"pill warn\">refused</span>', down: '<span class=\"pill bad\">down</span>', unknown: '<span class=\"pill mute\">not read</span>' };\n    function renderSources(v, now) {\n      const order = { down: 0, refused: 1, noclock: 2, stale: 3, retried: 4, unknown: 5, ok: 6 };\n      const rows = [...v.rows, ...v.extras].sort((a, b) => order[a.state] - order[b.state] || (a.lookup ? 1 : 0) - (b.lookup ? 1 : 0));\n      const tb = document.querySelector('#sources tbody');\n      tb.innerHTML = rows.map((r) => {\n        const link = r.id ? `<a class=\"ds\" href=\"https://${esc(r.host || 'data.cityofnewyork.us')}/d/${esc(r.id)}\" target=\"_blank\" rel=\"noopener\">${esc(r.id)}</a>` : '';\n        const h = r.h, f = r.f;\n        // Rows first; the clock read rides beside them and only speaks alone\n        // for a record whose rows this lane does not read (ok is null).\n        const clockCell = (c) => (!c ? '—' : c.ok ? `clock ok ${esc(ago(c.lastOkAt, now))}` : `<span class=\"pill warn\">clock HTTP ${esc(c.status ?? '—')}</span> ${esc(ago(c.failedAt, now))}`);\n        const clockBit = (c) => (c && c.ok === false ? ` · <span class=\"pill warn\">clock HTTP ${esc(c.status ?? '—')}</span>` : '');\n        const hCell = h ? (h.ok === null ? clockCell(h.clock) : (h.ok ? `${n(h.rows)} rows · ${h.calls} call${h.calls === 1 ? '' : 's'}${h.retries ? ` · ${h.retries} retr${h.retries === 1 ? 'y' : 'ies'}` : ''}` : `<span class=\"pill bad\">HTTP ${esc(h.status ?? '—')}</span> ${esc(h.error || '')}`) + clockBit(h.clock)) : (r.lookup ? 'not needed this run' : '—');\n        const fCell = f ? (f.ok === null ? clockCell(f.clock) : (f.ok ? `ok ${esc(ago(f.lastOkAt, now))}${f.retries ? ` · ${f.retries} retr${f.retries === 1 ? 'y' : 'ies'}` : ''}` : `<span class=\"pill bad\">HTTP ${esc(f.status ?? '—')}</span> ${esc(ago(f.failedAt, now))}`) + clockBit(f.clock)) : '—';\n        return `<tr>\n          <td><div class=\"name\">${esc(r.label)}</div><div class=\"agency\">${esc(r.agency)}${link ? ' · ' + link : ''}${r.lookup ? ' · lookup' : ''}</div></td>\n          <td class=\"mono nowrap\">${r.clock ? `${esc(ago(r.clock, now))}<span class=\"note\">${esc(etStamp(r.clock, now))}</span>` : (r.lookup || r.extra ? '—' : '<span class=\"pill mute\">unknown</span>')}</td>\n          <td class=\"mono\">${hCell}</td>\n          <td class=\"mono\">${fCell}</td>\n          <td>${PILL[r.state] || PILL.ok}${r.why ? `<span class=\"note\">${esc(r.why)}</span>` : ''}</td>\n        </tr>`;\n      }).join('');\n    }\n\n    function renderIncidents(v, now) {\n      const all = [...(v.hourly?.incidents || []).map((i) => ({ ...i, lane: i.lane || 'hourly' })), ...(v.live?.health?.incidents || []).map((i) => ({ ...i, lane: i.lane || 'fast' }))]\n        .sort((a, b) => (a.resolvedAt ? 1 : 0) - (b.resolvedAt ? 1 : 0) || b.at - a.at);\n      // GitHub knows about runs that died before writing a report.\n      const ghFails = (v.wf || []).filter((r) => r.name !== 'pinger' && (r.conclusion === 'failure' || r.conclusion === 'timed_out'))\n        .filter((r) => !all.some((i) => Math.abs(t(i.at) - t(r.startedAt)) < 40 * 60000))\n        .map((r) => ({ at: t(r.startedAt), lastAt: t(r.updatedAt), lane: r.name, source: 'run', status: null, error: `GitHub reports the run as ${r.conclusion}`, count: 1, resolvedAt: t(r.updatedAt), url: r.url, gh: true }));\n      const list = [...all, ...ghFails].sort((a, b) => (a.resolvedAt && !a.gh ? 1 : 0) - (b.resolvedAt && !b.gh ? 1 : 0) || b.at - a.at);\n      const el = document.getElementById('incidents');\n      if (!list.length) { el.innerHTML = '<div class=\"empty\">No incidents in the last 30 days.</div>'; return; }\n      el.innerHTML = list.map((i) => {\n        const label = i.source === 'run' ? (i.lane === 'hourly' ? 'Hourly sweep' : i.lane === 'fast' ? 'Five-minute lane' : i.lane) : labelOf(v.S, i.source);\n        const open = !i.resolvedAt;\n        const span = open ? `open since ${etStamp(i.at, now)}` : `${etStamp(i.at, now)} → ${etStamp(i.resolvedAt, now)} (${dur(t(i.resolvedAt) - t(i.at))})`;\n        return `<div class=\"row ${open ? 'bad' : 'mute'}\">\n          <div class=\"when\">${esc(span)}</div>\n          <div class=\"what\"><b>${esc(label)}</b> ${open ? '<span class=\"pill bad\">open</span>' : '<span class=\"pill mute\">resolved</span>'} <span class=\"d\">· ${esc(i.lane)} lane${i.status ? ` · HTTP ${esc(i.status)}` : ''}${i.count > 1 ? ` · ${i.count} consecutive failures` : ''}</span>\n          ${i.error ? `<div class=\"err\">${esc(i.error)}</div>` : ''}${i.url ? `<div class=\"err\"><a href=\"${esc(i.url)}\" target=\"_blank\" rel=\"noopener\">run log on GitHub</a></div>` : ''}</div>\n        </div>`;\n      }).join('');\n    }\n\n    function renderActivity(v, now) {\n      const items = [];\n      const S = v.S;\n      for (const r of v.hourly?.runs || []) {\n        const c = r.counts || {};\n        const level = r.outcome === 'ok' ? 'ok' : r.outcome === 'failed' ? 'bad' : 'warn';\n        const what = r.outcome === 'ok' ? `Feed rebuilt` : r.outcome === 'degraded' ? `Feed rebuilt, one stage carried` : r.outcome === 'upstream' ? `Sweep stopped early — city unavailable — previous feed kept` : `Sweep crashed`;\n        const detail = c.facades ? `${n(c.facades)} facade buildings · ${n(c.permits)} with a facade permit · ${n(c.contracts)} contracts · ${n(c.openings)} openings${c.new ? ` · new this week: ${n(c.new.buildings)} buildings, ${n(c.new.contracts)} contracts, ${n(c.new.openings)} openings` : ''}` : (r.error || '');\n        items.push({ at: t(r.at), level, lane: 'hourly', what: `${what} · ${dur(r.ms)}${r.failed?.length ? ` · failed: ${r.failed.map((k) => labelOf(S, k)).join(', ')}` : ''}`, detail });\n      }\n      for (const p of v.live?.health?.publications || []) items.push({ at: t(p.at), level: 'ok', lane: 'city', what: `${S[p.source]?.label || p.source} loaded rows`, detail: `the publisher's clock moved to ${etStamp(p.at, now)} · noticed ${ago(p.seenAt, now)}` });\n      for (const c of v.live?.changeLog || []) items.push({ at: t(c.at), level: 'ok', lane: 'fast', what: `A row arrived on the intraday lists`, detail: c.contracts || c.openings ? `fresh this week: ${n(c.contracts)} contract${c.contracts === 1 ? '' : 's'} · ${n(c.openings)} venue filing${c.openings === 1 ? '' : 's'}` : 'an award or a licence filing, new or corrected' });\n      for (const r of v.wf || []) {\n        if (r.name === 'pinger') {\n          if (r.status === 'in_progress') items.push({ at: t(r.startedAt), level: 'ok', lane: 'runner', what: 'Five-minute runner started', detail: `GitHub Actions · ${r.event.replace('_', ' ')} · running now`, url: r.url });\n          else if (r.conclusion === 'failure') items.push({ at: t(r.startedAt), level: 'bad', lane: 'runner', what: 'Five-minute runner failed', detail: 'GitHub Actions', url: r.url });\n          continue; // cancelled runners are the normal hand-over between runs\n        }\n        if (r.name === 'daily-digest') items.push({ at: t(r.startedAt), level: r.conclusion === 'success' ? 'ok' : r.status === 'in_progress' ? 'ok' : 'bad', lane: 'digest', what: r.conclusion === 'success' ? 'Digest sent' : r.status === 'in_progress' ? 'Digest sending' : `Digest ${r.conclusion}`, detail: 'GitHub Actions', url: r.url });\n        if (r.name === 'refresh-data' && (r.conclusion === 'failure' || r.conclusion === 'timed_out' || r.conclusion === 'cancelled')) items.push({ at: t(r.startedAt), level: 'bad', lane: 'hourly', what: `Hourly run ${r.conclusion} on GitHub`, detail: 'the runner itself, before or after the collector', url: r.url });\n      }\n      const horizon = items.some((i) => now - i.at < 2 * DAY) ? 2 * DAY : 7 * DAY;\n      document.getElementById('activity-note').textContent = horizon === 2 * DAY ? 'last 48 hours, newest first' : 'last 7 days, newest first';\n      const list = items.filter((i) => i.at && now - i.at < horizon).sort((a, b) => b.at - a.at).slice(0, 80);\n      const el = document.getElementById('activity');\n      if (!list.length) { el.innerHTML = '<div class=\"empty\">Nothing recorded yet.</div>'; return; }\n      el.innerHTML = list.map((i) => `<div class=\"row ${i.level}\">\n        <div class=\"when\">${esc(etStamp(i.at, now))}<br><span style=\"opacity:.7\">${esc(ago(i.at, now))}</span></div>\n        <div class=\"what\"><b>${esc(i.what)}</b> <span class=\"d\">· ${esc(i.lane)}</span>${i.detail ? `<div class=\"d\">${esc(i.detail)}</div>` : ''}${i.url ? `<div class=\"err\"><a href=\"${esc(i.url)}\" target=\"_blank\" rel=\"noopener\">run on GitHub</a></div>` : ''}</div>\n      </div>`).join('');\n    }\n\n    load();\n    setInterval(load, 60000);\n    setInterval(render, 15000);\n    document.addEventListener('visibilitychange', () => { if (!document.hidden && Date.now() - lastFetchAt > 30000) load(); });\n  </script>\n</body>\n</html>\n";
